struct MovingAverage
{
    static constexpr int32_t Kind_Simple = 0;
    static constexpr int32_t Kind_Exponential = 1;
    static constexpr int32_t Kind_Gaussian = 2;
    struct Simple_Members { int32_t WindowSize; };
    struct Exponential_Members { Proportion Alpha; };
    struct Gaussian_Members { int32_t WindowSize; double StandardDeviation; };
    static constexpr size_t Storage0_ = sizeof(Simple_Members);
    static constexpr size_t Storage1_ = Storage0_ > sizeof(Exponential_Members) ? Storage0_ : sizeof(Exponential_Members);
    static constexpr size_t Storage2_ = Storage1_ > sizeof(Gaussian_Members) ? Storage1_ : sizeof(Gaussian_Members);
    int32_t Kind;
    union
    {
        alignas(Simple_Members) alignas(Exponential_Members) alignas(Gaussian_Members) unsigned char Zero_[Storage2_] = {};
        Simple_Members As_Simple;
        Exponential_Members As_Exponential;
        Gaussian_Members As_Gaussian;
    };
};

