// Structural equality and hash helpers (arrays compare element-wise).
template <class T> inline bool eq_(const T& a, const T& b) { return a == b; }
template <class T> inline bool eq_(const Array<T>& a, const Array<T>& b)
{
    if (a.count != b.count) return false;
    for (int32_t i = 0; i < a.count; i++) if (!eq_(a.data[i], b.data[i])) return false;
    return true;
}
inline int32_t mix_(int32_t h, int32_t v) { return (int32_t)(((uint32_t)h * 16777619u) ^ (uint32_t)v); }
inline int32_t hash_(double x) { uint64_t u; std::memcpy(&u, &x, sizeof u); return (int32_t)(u ^ (u >> 32)); }
inline int32_t hash_(int32_t x) { return x; }
inline int32_t hash_(bool x) { return x ? 1 : 0; }
inline int32_t hash_(char16_t x) { return (int32_t)x; }
inline int32_t hash_(const Bytes& b) { return Hash(b); }
inline int32_t hash_(const String& s) { int32_t h = 17; for (char16_t c : s) h = mix_(h, (int32_t)c); return h; }
template <class T> inline int32_t hash_(const Array<T>& a) { return a.count; }

inline bool operator==(const Angle& a, const Angle& b) { return eq_(a.Radians, b.Radians); }
inline bool operator!=(const Angle& a, const Angle& b) { return !(a == b); }
inline bool operator==(const Axis3D& a, const Axis3D& b) { return a.Kind == b.Kind; }
inline bool operator!=(const Axis3D& a, const Axis3D& b) { return !(a == b); }
inline bool operator==(const Axis2D& a, const Axis2D& b) { return a.Kind == b.Kind; }
inline bool operator!=(const Axis2D& a, const Axis2D& b) { return !(a == b); }
inline bool operator==(const SignedAxis3D& a, const SignedAxis3D& b) { return a.Kind == b.Kind; }
inline bool operator!=(const SignedAxis3D& a, const SignedAxis3D& b) { return !(a == b); }
template <class T> inline bool operator==(const JaggedArray<T>& a, const JaggedArray<T>& b) { return eq_(a.Offsets, b.Offsets) && eq_(a.Values, b.Values); }
template <class T> inline bool operator!=(const JaggedArray<T>& a, const JaggedArray<T>& b) { return !(a == b); }
template <class T> inline int32_t hash_(const JaggedArray<T>& a) { int32_t h = 17; h = mix_(h, hash_(a.Offsets)); return h; }
inline bool operator==(const Color& a, const Color& b) { return eq_(a.R, b.R) && eq_(a.G, b.G) && eq_(a.B, b.B) && eq_(a.A, b.A); }
inline bool operator!=(const Color& a, const Color& b) { return !(a == b); }
inline bool operator==(const Color8& a, const Color8& b) { return eq_(a.R, b.R) && eq_(a.G, b.G) && eq_(a.B, b.B) && eq_(a.A, b.A); }
inline bool operator!=(const Color8& a, const Color8& b) { return !(a == b); }
inline bool operator==(const ColorHSV& a, const ColorHSV& b) { return eq_(a.Hue, b.Hue) && eq_(a.Saturation, b.Saturation) && eq_(a.Value, b.Value); }
inline bool operator!=(const ColorHSV& a, const ColorHSV& b) { return !(a == b); }
inline bool operator==(const ColorHSL& a, const ColorHSL& b) { return eq_(a.Hue, b.Hue) && eq_(a.Saturation, b.Saturation) && eq_(a.Lightness, b.Lightness); }
inline bool operator!=(const ColorHSL& a, const ColorHSL& b) { return !(a == b); }
inline bool operator==(const ColorStop& a, const ColorStop& b) { return eq_(a.Position, b.Position) && eq_(a.Color, b.Color); }
inline bool operator!=(const ColorStop& a, const ColorStop& b) { return !(a == b); }
inline bool operator==(const ColorGradient& a, const ColorGradient& b) { return eq_(a.Stops, b.Stops); }
inline bool operator!=(const ColorGradient& a, const ColorGradient& b) { return !(a == b); }
inline bool operator==(const GraphVertexIndex& a, const GraphVertexIndex& b) { return eq_(a.Value, b.Value); }
inline bool operator!=(const GraphVertexIndex& a, const GraphVertexIndex& b) { return !(a == b); }
inline bool operator==(const GraphEdge& a, const GraphEdge& b) { return eq_(a.Source, b.Source) && eq_(a.Target, b.Target); }
inline bool operator!=(const GraphEdge& a, const GraphEdge& b) { return !(a == b); }
inline bool operator==(const Graph& a, const Graph& b) { return eq_(a.VertexCount, b.VertexCount) && eq_(a.Edges, b.Edges) && eq_(a.Directed, b.Directed); }
inline bool operator!=(const Graph& a, const Graph& b) { return !(a == b); }
inline bool operator==(const WeightedEdge& a, const WeightedEdge& b) { return eq_(a.Source, b.Source) && eq_(a.Target, b.Target) && eq_(a.Weight, b.Weight); }
inline bool operator!=(const WeightedEdge& a, const WeightedEdge& b) { return !(a == b); }
inline bool operator==(const WeightedGraph& a, const WeightedGraph& b) { return eq_(a.VertexCount, b.VertexCount) && eq_(a.Edges, b.Edges) && eq_(a.Directed, b.Directed); }
inline bool operator!=(const WeightedGraph& a, const WeightedGraph& b) { return !(a == b); }
inline bool operator==(const AdjacencyMatrix& a, const AdjacencyMatrix& b) { return eq_(a.VertexCount, b.VertexCount) && eq_(a.Weights, b.Weights); }
inline bool operator!=(const AdjacencyMatrix& a, const AdjacencyMatrix& b) { return !(a == b); }
inline bool operator==(const AdjacencyStructure& a, const AdjacencyStructure& b) { return eq_(a.VertexCount, b.VertexCount) && eq_(a.NeighborOffsets, b.NeighborOffsets) && eq_(a.NeighborIndices, b.NeighborIndices); }
inline bool operator!=(const AdjacencyStructure& a, const AdjacencyStructure& b) { return !(a == b); }
inline bool operator==(const Hypergraph& a, const Hypergraph& b) { return eq_(a.VertexCount, b.VertexCount) && eq_(a.HyperedgeOffsets, b.HyperedgeOffsets) && eq_(a.HyperedgeVertices, b.HyperedgeVertices); }
inline bool operator!=(const Hypergraph& a, const Hypergraph& b) { return !(a == b); }
inline bool operator==(const GraphPath& a, const GraphPath& b) { return eq_(a.VertexIndices, b.VertexIndices) && eq_(a.TotalWeight, b.TotalWeight); }
inline bool operator!=(const GraphPath& a, const GraphPath& b) { return !(a == b); }
inline bool operator==(const ShortestPathTree& a, const ShortestPathTree& b) { return eq_(a.SourceIndex, b.SourceIndex) && eq_(a.ParentIndices, b.ParentIndices) && eq_(a.Distances, b.Distances); }
inline bool operator!=(const ShortestPathTree& a, const ShortestPathTree& b) { return !(a == b); }
inline bool operator==(const SpanningTree& a, const SpanningTree& b) { return eq_(a.ParentIndices, b.ParentIndices) && eq_(a.RootIndex, b.RootIndex); }
inline bool operator!=(const SpanningTree& a, const SpanningTree& b) { return !(a == b); }
inline bool operator==(const ConnectedComponents& a, const ConnectedComponents& b) { return eq_(a.ComponentLabels, b.ComponentLabels) && eq_(a.ComponentCount, b.ComponentCount); }
inline bool operator!=(const ConnectedComponents& a, const ConnectedComponents& b) { return !(a == b); }
inline bool operator==(const TopologicalOrder& a, const TopologicalOrder& b) { return eq_(a.OrderedVertexIndices, b.OrderedVertexIndices) && eq_(a.IsValid, b.IsValid); }
inline bool operator!=(const TopologicalOrder& a, const TopologicalOrder& b) { return !(a == b); }
